import ast
import hashlib
import json
import subprocess
from pathlib import Path

ROOT = Path('C:/Users/郑曾波/Projects/company-wiki')
WT = ROOT / 'tmp/w23-r6'
OUT = ROOT / 'tmp/g6'
RESULTS = ROOT / 'docs/plans/du11-source-closure-2026-10-18/review/architecture-quality-20261101/implementation-results'
author = json.loads((RESULTS / 'R6-daily-feedback-simplification.json').read_text(encoding='utf-8'))

def git(*args):
    return subprocess.check_output(['git', *args], cwd=WT)

def sha(data):
    return hashlib.sha256(data).hexdigest()

manifest = {}
for file, expected in author['changed_files_sha256'].items():
    data = (WT / file).read_bytes()
    blob = git('show', f'819cef31:{file}')
    manifest[file] = {'raw_sha256': sha(data), 'author_sha256': expected,
                      'author_raw_match': sha(data) == expected,
                      'git_blob_lf_sha256': sha(blob),
                      'git_blob_lf_match': data.replace(b'\r\n', b'\n') == blob}
assert all(row['author_raw_match'] and row['git_blob_lf_match'] for row in manifest.values())
old = ast.parse(git('show', '848b4ee0:tools/pre_push_gate.py').decode())
new = ast.parse((WT / 'tools/pre_push_gate.py').read_text(encoding='utf-8'))

def nodes(tree):
    out = {}
    for n in tree.body:
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out[n.name] = n
        elif isinstance(n, ast.Assign):
            for target in n.targets:
                if isinstance(target, ast.Name):
                    out[target.id] = n
    return out

a, b = nodes(old), nodes(new)
kept = ['FAST_CONTRACT_CASES', 'CURRENT_CI_REGRESSION_CASES',
        'DAILY_PUSH_TIMEOUT_SECONDS', 'STDOUT_CAP_BYTES', 'STDERR_CAP_BYTES',
        '_run', '_run_pytest_gate', '_dispatch_gate', '_open_scratch']
ast_equal = {name: ast.dump(a[name], include_attributes=False) == ast.dump(b[name], include_attributes=False)
             for name in kept}
assert all(ast_equal.values())

def full_modes(tree):
    main = nodes(tree)['main']
    chosen = []
    for n in main.body:
        if isinstance(n, (ast.Assign, ast.AnnAssign)):
            targets = [getattr(n, 'target', None), *getattr(n, 'targets', [])]
            if any(isinstance(t, ast.Name) and t.id in {'gates', 'focused_contract_gate', 'fast_contract_gate'} for t in targets):
                chosen.append(n)
        if isinstance(n, ast.If) and isinstance(n.test, ast.Attribute) and n.test.attr == 'fast_contracts_only':
            chosen.append(n)
        if isinstance(n, ast.For):
            chosen.append(n)
    return [ast.dump(n, include_attributes=False) for n in chosen]

full_equal = full_modes(old) == full_modes(new)
assert full_equal
fixed_smoke_nodes = len(b['FAST_CONTRACT_CASES'].value.elts) - 1 + len(b['CURRENT_CI_REGRESSION_CASES'].value.elts)
unchanged = {}
for file in ['.github/workflows/ci.yml', '.pre-commit-config.yaml', 'tools/changed_unit_tests.py',
             'src/company_wiki/_bounded_process.py', 'src/company_wiki/_process_tree.py']:
    baseline, candidate = git('show', f'848b4ee0:{file}'), git('show', f'819cef31:{file}')
    unchanged[file] = {'baseline_equals_candidate': baseline == candidate,
                       'candidate_blob_sha256': sha(candidate),
                       'working_lf_equals_candidate': (WT / file).read_bytes().replace(b'\r\n', b'\n') == candidate}
assert all(v['baseline_equals_candidate'] and v['working_lf_equals_candidate'] for v in unchanged.values())
hook_diff = git('diff', '--', '.githooks/pre-push').decode()
assert hook_diff.strip().endswith('old mode 100755\nnew mode 100644')
head = git('rev-parse', 'HEAD').decode().strip()
assert head == '819cef31a4f2db7fa05bfe50901725f7a0dad016'
out = {'head': head, 'branch': git('branch', '--show-current').decode().strip(),
       'base': git('rev-parse', '848b4ee0').decode().strip(), 'manifest': manifest,
       'retained_ast_equal': ast_equal, 'full_modes_execution_ast_equal': full_equal,
       'fixed_smoke_target_count': fixed_smoke_nodes, 'unchanged': unchanged,
       'deleted_obsolete_test_absent': not (WT / 'tests/unit/test_known_push_scope.py').exists(),
       'working_status': git('status', '--short').decode().strip(),
       'foreign_hook_mode_only_diff': hook_diff,
       'old_timeout_receipts': {name: {'exists': (ROOT / name).exists(), 'sha256': sha((ROOT / name).read_bytes()) if (ROOT / name).exists() else None}
         for name in ['.planning/architecture-quality-20261101/r6-publication/r3-candidate-push.json', '.planning/architecture-quality-20261101/r6-publication/r3-candidate-push.log']}}
(OUT / 'seal.json').write_text(json.dumps(out, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'head': head, 'seven_sha_pass': len(manifest), 'ast_pass': len(ast_equal),
                  'full_modes_equal': full_equal, 'fixed_targets': fixed_smoke_nodes,
                  'unchanged_files': len(unchanged), 'status': out['working_status']}, ensure_ascii=False))
